class Solution {
public:
    int solve(vector<string> nums,string s,int index)
    {
        unordered_set<char> ust(s.begin(),s.end());
        if(s.size()!=ust.size())
            return 0;
        int ans=s.size();
        for(int i=index;i<nums.size();i++)
            ans=max(ans,solve(nums,s+nums[i],i+1));
        return ans;
    }
    int maxLength(vector<string>& arr) {
        int ans=solve(arr,"",0);
        return ans;
    }
};

class Solution {
public:
    int ans = 0;

    int maxLength(vector<string>& arr) {
        vector<bool> flags(26, false);
        dfs(0, arr, flags);
        return ans;
    }

    void dfs(int p, vector<string>& arr, vector<bool>& flags) {
        for (int i = p; i < arr.size(); i++) {
            vector<bool> prev_flags(flags);
            bool flag = true;
            for (int j = 0; j < arr[i].length(); j++) {
                if (flags[arr[i][j] - 'a'] == true) {
                    flag = false;
                    break;
                } else {
                    flags[arr[i][j] - 'a'] = true;
                }
            }
            if (flag == true) {
                int cur_ans = 0;
                for (int j = 0; j < flags.size(); j++) {
                    if (flags[j] == true) {
                        cur_ans += 1;
                    }
                }
                ans = max(ans, cur_ans);
                dfs(i + 1, arr, flags);
            }
            flags.assign(prev_flags.begin(), prev_flags.end());
        }
    }
};

